sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.gnf-footer *,
.gnf-footer *::before,
.gnf-footer *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  list-style: none;
}

/* ── Wrapper ── */
.gnf-footer {
  font-family: 'Inter', 'Segoe UI', sans-serif;
  background: #141418;
  width: calc(100% + 30px);
  margin-left: -15px;
  margin-right: -15px;
}

.gnf-inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 52px;
}

/* ── Top row ── */
.gnf-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 60px;
  padding: 48px 0 40px;
}

/* ── Brand ── */
.gnf-brand {
  display: flex;
  flex-direction: column;
  gap: 14px;
  max-width: 220px;
}

.gnf-logo {
  display: flex;
  align-items: center;
}

.gnf-logo-img {
  height: 28px;
  width: auto;
  object-fit: contain;
  display: block;
  opacity: 0.90;
}

.gnf-tagline {
  font-size: 12.5px;
  color: rgba(255,255,255,0.38);
  line-height: 1.70;
  font-weight: 400;
}

/* ── Nav columns ── */
.gnf-nav {
  display: flex;
  gap: 52px;
  flex-shrink: 0;
}

.gnf-col {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.gnf-col-heading {
  font-size: 11px;
  font-weight: 600;
  color: rgba(255,255,255,0.55);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.gnf-col-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.gnf-link {
  font-size: 13px;
  font-weight: 400;
  color: rgba(255,255,255,0.45);
  text-decoration: none !important;
  transition: color 0.16s ease;
  white-space: nowrap;
}
.gnf-link:hover {
  color: rgba(255,255,255,0.85);
}

.gnf-text {
  font-size: 13px;
  color: rgba(255,255,255,0.30);
  white-space: nowrap;
  display: block;
}

/* ── Bottom bar ── */
.gnf-bottom {
  padding: 18px 0 22px;
  border-top: 1px solid rgba(255,255,255,0.07);
}

.gnf-copyright {
  font-size: 11.5px;
  color: rgba(255,255,255,0.25);
}

/* ── Responsive ── */
@media (max-width: 900px) {
  .gnf-nav { gap: 32px; flex-wrap: wrap; }
}

@media (max-width: 768px) {
  .gnf-top   { flex-direction: column; gap: 36px; padding: 36px 0 32px; }
  .gnf-inner { padding: 0 28px; }
  .gnf-brand { max-width: 100%; }
}

@media (max-width: 520px) {
  .gnf-inner  { padding: 0 18px; }
  .gnf-nav    { gap: 28px; }
}
